package com.dunerealms.atelier;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.sql.*;import java.math.BigDecimal;import java.util.*;
class ArcStoreTest {
 final UUID player=UUID.randomUUID();
 Connection database(String funding)throws Exception{Connection c=DriverManager.getConnection("jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;DATABASE_TO_LOWER=TRUE");try(Statement s=c.createStatement()){s.execute("CREATE TABLE dune_kit_sales(buyer_uuid VARCHAR(36),seller_uuid VARCHAR(36),rarity VARCHAR(16),delivered_at BIGINT,quantity INT,gross_cents BIGINT,commerce_kind VARCHAR(16) NOT NULL DEFAULT 'personal_sale')");s.execute("CREATE TABLE dune_kit_arc_claims(player_uuid VARCHAR(36),stage_index INT,reward_cents BIGINT,claimed_at BIGINT,PRIMARY KEY(player_uuid,stage_index))");s.execute("CREATE TABLE dune_staff_bank_wallet(account_key VARCHAR(16) PRIMARY KEY,balance DECIMAL(20,2),updated_at BIGINT)");s.execute("CREATE TABLE dune_economy_balances(uuid VARCHAR(36) PRIMARY KEY,balance DECIMAL(20,2))");s.execute("CREATE TABLE dune_staff_bank_ledger(id VARCHAR(36) PRIMARY KEY,player_uuid VARCHAR(36),action VARCHAR(32),delta DECIMAL(20,2),balance_after DECIMAL(20,2),created_at BIGINT,reference VARCHAR(100) UNIQUE)");s.execute("INSERT INTO dune_staff_bank_wallet VALUES('network',"+funding+",0)");s.execute("INSERT INTO dune_economy_balances VALUES('"+player+"',0)");}return c;}
 void sale(Connection c,UUID buyer,Long delivered,String quality,long gross)throws Exception{try(PreparedStatement q=c.prepareStatement("INSERT INTO dune_kit_sales(buyer_uuid,seller_uuid,rarity,delivered_at,quantity,gross_cents) VALUES(?,?,?,?,1,?)")){q.setString(1,buyer.toString());q.setString(2,player.toString());q.setString(3,quality);if(delivered==null)q.setNull(4,Types.BIGINT);else q.setLong(4,delivered);q.setLong(5,gross);q.executeUpdate();}}
 void qualify(Connection c)throws Exception{for(int i=0;i<3;i++)sale(c,UUID.randomUUID(),1000L,"common",10000);}
 BigDecimal sum(Connection c)throws Exception{try(Statement q=c.createStatement();ResultSet r=q.executeQuery("SELECT (SELECT SUM(balance) FROM dune_staff_bank_wallet)+(SELECT SUM(balance) FROM dune_economy_balances)")){r.next();return r.getBigDecimal(1);}}
 @Test void paidDeliveredExternalUniqueBuyersOnly()throws Exception{try(Connection c=database("50")){UUID buyer=UUID.randomUUID();sale(c,buyer,1000L,"common",10000);sale(c,buyer,2000L,"common",10000);sale(c,player,1000L,"common",10000);sale(c,UUID.randomUUID(),null,"common",10000);sale(c,UUID.randomUUID(),1000L,"common",9999);assertEquals(1,ArcStore.sales(c,player,0));}}
 @Test void officialFactionAndServerSalesNeverAdvancePersonalDesignChapters()throws Exception{try(Connection c=database("50")){for(String kind:List.of("official_sale","faction_sale","server_sale")){UUID buyer=UUID.randomUUID();sale(c,buyer,1000L,"common",10000);try(PreparedStatement q=c.prepareStatement("UPDATE dune_kit_sales SET commerce_kind=? WHERE buyer_uuid=?")){q.setString(1,kind);q.setString(2,buyer.toString());q.executeUpdate();}}assertEquals(0,ArcStore.sales(c,player,0));sale(c,UUID.randomUUID(),1000L,"common",10000);assertEquals(1,ArcStore.sales(c,player,0));}}
 @Test void rewardsConserveExistingMoneyAndAreExactlyOnce()throws Exception{try(Connection c=database("50")){qualify(c);c.setAutoCommit(false);ArcStore store=new ArcStore();assertEquals(ArcStore.Claim.credited,store.claim(c,player,0));c.commit();assertEquals(ArcStore.Claim.already_claimed,store.claim(c,player,0));c.commit();assertEquals(new BigDecimal("50.00"),sum(c));try(Statement q=c.createStatement();ResultSet r=q.executeQuery("SELECT balance FROM dune_economy_balances")){r.next();assertEquals(new BigDecimal("10.00"),r.getBigDecimal(1));}}}
 @Test void unfundedRewardCreatesNoClaimOrMoney()throws Exception{try(Connection c=database("0")){qualify(c);c.setAutoCommit(false);assertEquals(ArcStore.Claim.pending_funding,new ArcStore().claim(c,player,0));c.commit();assertEquals(0,ArcStore.claims(c,player));assertEquals(new BigDecimal("0.00"),sum(c));}}
 @Test void transactionRollbackRestoresTreasuryWalletAndReceipt()throws Exception{try(Connection c=database("50")){qualify(c);c.setAutoCommit(false);new ArcStore().claim(c,player,0);c.rollback();assertEquals(0,ArcStore.claims(c,player));assertEquals(new BigDecimal("50.00"),sum(c));}}
 @Test void cannotSkipIncompleteChapter()throws Exception{try(Connection c=database("50")){qualify(c);c.setAutoCommit(false);assertThrows(SQLException.class,()->new ArcStore().claim(c,player,1));c.rollback();assertEquals(0,ArcStore.claims(c,player));}}
 @Test void canonicalStoryAndFiveCosmeticTemplatesMatchEconomy(){for(int i=0;i<5;i++){assertFalse(ArcLore.description(i).isBlank());assertFalse(ArcLore.templateName(i).isBlank());}assertEquals(38500,Arrays.stream(ArcStore.REWARDS).sum());}
}
